<table class="enterprise-table" <?=$withFilters?'data-butchery-history="'.e($kind).'"':''?>><thead><tr><th>Date</th><th>Référence / lot</th><th><?=$kind==='sales'?'Client':'Destination'?></th><th>Quantité</th><?php if($kind==='sales'):?><th>Montant</th><?php endif;?><th>Statut</th><th>Actions</th></tr></thead><tbody>
<?php foreach($outgoingRows as $row):$date=$kind==='sales'?$row['sold_at']:$row['created_at'];?>
<tr data-status="<?=e($row['status'])?>" data-date="<?=e(substr($date,0,10))?>"><td data-order="<?=e(strtotime($date))?>"><?=e($outgoingDate($date))?></td><td><strong><?=e($kind==='sales'?$row['sale_number']:$row['transfer_number'])?></strong><small><?=e($row['item_name'].' · '.$row['lot_number'])?></small></td><td><?=e($kind==='sales'?$row['customer_name']:$row['destination_name'])?></td><td data-order="<?=e($row['quantity_kg'])?>"><?=e(number_format((float)$row['quantity_kg'],3,',',' '))?> kg</td><?php if($kind==='sales'):$amount=(float)$row['quantity_kg']*(float)$row['unit_price'];?><td data-order="<?=e($amount)?>"><?=e(number_format($amount,2,',',' '))?></td><?php endif;?><td><span class="butchery-status <?=in_array($row['status'],['validated','received'],true)?'butchery-status-success':'butchery-status-pending'?>"><?=e($outgoingStatuses[$row['status']]??$row['status'])?></span></td><td><div class="butchery-production-actions"><?=$kind==='transfers'?($outgoingActions[$row['id']]??''):''?><button class="btn-secondary" type="button" data-workspace-modal-open="<?=e('outgoing-'.$kind.'-'.$row['id'])?>">Consulter</button></div></td></tr><?php endforeach;?></tbody></table>
